# POST /api/sheets/{sheetId}/people/{personId}/hold — put a person on hold (held: true) or take them off it (false).
# A body without held is a 400, a person not on the sheet a 404, and a person already so a 400, none writing anything.
# While held, the person's OPEN claims count in no live total; their SETTLED claims still do. Responds with the person
# as stored.
validate:
  class: net.officefloor.hq.app.person.ValidateHold
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: hold
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonHold
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes PERSON_HELD or PERSON_RELEASED to the audit file once the hold is stored. Then writes the
 * figures the change moved (see Rollup). */
public class RecordPersonHold {
    public void record(@Val Person person, @Val Hold hold, @Val RollupBefore before, Rollup rollup, Audit audit) {
        audit.record((hold.held() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + person.sheetId() + " by="
                + hold.by() + " name=" + person.name());
        rollup.record(person.sheetId(), hold.by(), before);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Puts the person on hold or takes them off it; holding one already held, or releasing one not held, is refused. */
public class HoldPerson {
    public void hold(@Val Person person, @Val Hold hold, PersonRepository people, Out<Person> held)
            throws InvalidPersonException {
        if (!people.hold(person.sheetId(), person.id(), hold.held())) {
            throw new InvalidPersonException(hold.held() ? "The person is already on hold" : "The person is not on hold");
        }
        held.set(new Person(person.id(), person.sheetId(), person.name(), person.grade(), person.version(),
                person.retiredFrom(), hold.held(), person.grades()));
    }
}
package net.officefloor.hq.app.person;

/** A hold once validated: whether the person is to be held (true) or released (false), and who does it. */
public record Hold(boolean held, String by) {
}
package net.officefloor.hq.app.person;

/** Body of holding a person: whether they are to be held (true) or released (false), and who does it. */
public record HoldRequest(Boolean held, String by) {
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: whether to hold or release is required. */
public class ValidateHold {
    public void validate(@RequestBody HoldRequest request, Out<Hold> hold) throws InvalidPersonException {
        if (request == null || request.held() == null) {
            throw new InvalidPersonException("Whether to hold or release is required");
        }
        hold.set(new Hold(request.held(), request.by() == null ? "" : request.by().trim()));
    }
}
-- A person can be put on hold and taken off it again. While held, their OPEN claims count in no live total (their own
-- claimed and due-total, the sheet's totals, a period's due-total); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { peopleKey, type Person } from '../people/people';

function HoldHead() {
  return (
    <>
      <th>On hold</th>
      <th />
    </>
  );
}

/** Whether the person is on hold, and the button that holds or releases them. While held, their OPEN or PENDING claims count in
 *  no live total; their SETTLED claims still do. A refused hold or release shows the row's error. */
function PersonHold({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const submit = useSubmitOnce();
  const hold = useMutation({
    mutationFn: (held: boolean) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/hold`, { held, by: user }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
    onSettled: submit.end,
  });

  return (
    <>
      <td data-testid="person-hold">{person.held ? 'yes' : 'no'}</td>
      <td>
        <button
          type="button"
          data-testid="person-hold-toggle"
          disabled={hold.isPending}
          onClick={() => {
            if (!submit.begin()) return;
            hold.reset();
            hold.mutate(!person.held);
          }}
        >
          {person.held ? 'Release' : 'Hold'}
        </button>
        {hold.isError && <span data-testid="person-error"> Could not change this person's hold.</span>}
      </td>
    </>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 50, Component: HoldHead }),
  PersonRow.fill({ order: 50, Component: PersonHold }),
];
