/** A person on a sheet: a name (unique on the sheet, case ignored; kept without surrounding spaces) and a grade, one of A, B or C.
 *  The grade is dated: {@code grades} are the grades recorded, by from-date (the one with none, the first given, first), and
 *  {@code grade} is the one in force on the sheet's today.
 *  The version is 0 when added and goes up by one on each stored edit. {@code retiredFrom} (yyyy-MM-dd) is the date the
 *  person is retired from, null when not retired; a person with one counts as retired at once, whatever the date.
 *  {@code held} is whether the person is on hold: their OPEN or PENDING claims then count in no live total. */
public record Person(long id, String sheetId, String name, String grade, long version, String retiredFrom, boolean held,
        List<PersonGrade> grades) {

    public boolean retired() {
        return retiredFrom != null;
    }

    /** Whether a claim of the person may be dated {@code date}: not after their retirement date. */
    public boolean mayClaimOn(java.time.LocalDate date) {
        return retiredFrom == null || !date.isAfter(java.time.LocalDate.parse(retiredFrom));
    }

    /** The grade in force on a date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate date) {
        return gradeOn(grades, date);
    }

    /** The grade in force on a date among these, by from-date; null when there are none. */
    public static String gradeOn(List<PersonGrade> grades, LocalDate date) {
        PersonGrade found = null;
        for (PersonGrade g : grades) {
            if (g.from() != null && g.from().isAfter(date)) {
                continue;
            }
            if (found == null || found.from() == null || (g.from() != null && g.from().isAfter(found.from()))) {
                found = g;
            }
        }
        return found == null ? null : found.grade();
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;

/** The figures a claim has: live, fixed when settled, or bound by a statement. */
public final class ClaimDue {

    private ClaimDue() {
    }

    /** Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED claims do. */
    public static boolean counts(Claim claim) {
        return isOpen(claim) || claim.status() == ClaimStatus.SETTLED;
    }

    /** Whether a claim is open: OPEN, or PENDING (handled like an OPEN claim but for its statement binding). */
    public static boolean isOpen(Claim claim) {
        return claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING;
    }

    /** Whether a claim counts toward the live totals (claimed, due-totals, a period's due-total): one that counts,
     *  unless it is open (OPEN or PENDING) and its person is on hold. */
    public static boolean countsLive(Claim claim, boolean held) {
        return counts(claim) && !(held && isOpen(claim));
    }

    /** The claim's amount at the grade's rate in force on its date, rounded to two decimals by the claim's rounding
     *  (see Rounding), and at least the sheet's floor (a correction has no floor); null when no rate applies. */
    public static BigDecimal live(Claim claim, String grade, RateRepository rates, BigDecimal floor, Rounding rounding) {
        Rate rate = rates.find(claim.sheetId(), grade, claim.date());
        if (rate == null) {
            return null;
        }
        BigDecimal due = claim.amount().multiply(rate.rate()).movePointLeft(2).setScale(2, rounding.mode(claim));
        return isCorrection(claim) ? due : due.max(floor);
    }

    /** Whether the claim is a correction: its amount is negative. */
    public static boolean isCorrection(Claim claim) {
        return claim.amount().signum() < 0;
    }

    /** The figure the claim shows: fixed when settled, else the one a statement bound it to (never while PENDING),
     *  else live; null when it has none (n/a). */
    public static BigDecimal figure(Claim claim, String grade, RateRepository rates, BigDecimal floor,
            Rounding rounding) {
        if (claim.due() != null) {
            return claim.due();
        }
        return bound(claim) ? claim.statedDue() : live(claim, grade, rates, floor, rounding);
    }

    /** Whether the claim keeps a figure whatever the rates are: fixed when settled, or bound by a statement. */
    public static boolean kept(Claim claim) {
        return claim.due() != null || (bound(claim) && claim.statedDue() != null);
    }

    /** Whether a statement binds the claim now: it is stated and not PENDING. */
    public static boolean bound(Claim claim) {
        return claim.stated() && claim.status() != ClaimStatus.PENDING;
    }
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The stored people, kept per sheet. Ids are assigned in the order people are added. A person's grades are kept
 *  dated in person_grade; a person read carries them all, and the grade in force on the sheet's today. */
@Repository
public class PersonRepository {

    private static final String COLUMNS = "id, sheet_id, name, version, retired_from, held";

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;

    public PersonRepository(JdbcTemplate jdbc, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    public List<Person> list(String sheetId) {
        return withGrades(sheetId, jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? ORDER BY id",
                PersonRepository::map, sheetId));
    }

    public Person find(String sheetId, long id) {
        return first(sheetId, jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ?",
                PersonRepository::map, sheetId, id));
    }

    /** The person on the sheet with this name, case ignored; null when there is none. */
    public Person findByName(String sheetId, String name) {
        return first(sheetId, jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND name_key = LOWER(?)",
                PersonRepository::map, sheetId, name));
    }

    private Person first(String sheetId, List<Person> found) {
        return found.isEmpty() ? null : withGrades(sheetId, found).get(0);
    }

    /** The people with their grades, and the grade in force on the sheet's today. */
    private List<Person> withGrades(String sheetId, List<Person> found) {
        if (found.isEmpty()) {
            return found;
        }
        Map<Long, List<PersonGrade>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, grade FROM person_grade WHERE sheet_id = ? ORDER BY person_id, from_date NULLS FIRST",
                (ResultSet rs) -> {
                    Date from = rs.getDate("from_date");
                    grades.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new PersonGrade(rs.getString("grade"), from == null ? null : from.toLocalDate()));
                }, sheetId);
        LocalDate today = sheets.today(sheetId);
        List<Person> people = new ArrayList<>();
        for (Person p : found) {
            List<PersonGrade> mine = List.copyOf(grades.getOrDefault(p.id(), List.of()));
            people.add(new Person(p.id(), p.sheetId(), p.name(), Person.gradeOn(mine, today), p.version(), p.retiredFrom(),
                    p.held(), mine));
        }
        return people;
    }

    /** Whether a person on the sheet other than {@code exceptId} (0: anyone) has this name, case ignored. */
    public boolean nameTaken(String sheetId, String name, long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(?) AND id <> ?",
                Integer.class, sheetId, name, exceptId);
        return n != null && n > 0;
    }

    /** The unique (sheet_id, name_key) index refuses a name taken by a concurrent add or edit. */
    public Person add(String sheetId, String name, String grade) throws DuplicatePersonNameException {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        try {
            jdbc.update(con -> {
                PreparedStatement ps = con.prepareStatement("INSERT INTO person (sheet_id, name, grade) VALUES (?, ?, ?)",
                        new String[] { "id" });
                ps.setString(1, sheetId);
                ps.setString(2, name);
                ps.setString(3, grade);
                return ps;
            }, keys);
        } catch (DuplicateKeyException e) {
            throw new DuplicatePersonNameException(name);
        }
        long id = keys.getKey().longValue();
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, NULL, ?)", sheetId, id, grade);
        return new Person(id, sheetId, name, grade, 0, null, false, List.of(new PersonGrade(grade, null)));
    }

    /** Stores the person as its new version, with its grades, only while the stored one is still {@code fromVersion}:
     *  a save that lands in between refuses this one. */
    public void update(Person person, long fromVersion) throws DuplicatePersonNameException, StalePersonException {
        int n;
        try {
            n = jdbc.update("UPDATE person SET name = ?, version = ? WHERE sheet_id = ? AND id = ? AND version = ?",
                    person.name(), person.version(), person.sheetId(), person.id(), fromVersion);
        } catch (DuplicateKeyException e) {
            throw new DuplicatePersonNameException(person.name());
        }
        if (n == 0) {
            throw new StalePersonException(person.id());
        }
        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", person.sheetId(), person.id());
        for (PersonGrade g : person.grades()) {
            jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)",
                    person.sheetId(), person.id(), g.from() == null ? null : Date.valueOf(g.from()), g.grade());
        }
    }

    /** Retires the person from the date (replacing any earlier retirement date). */
    public void retire(String sheetId, long id, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet_id = ? AND id = ?", Date.valueOf(from), sheetId, id);
    }

    /** Puts the person on hold (true) or takes them off it (false), only while they are not already so; false when
     *  they already were. */
    public boolean hold(String sheetId, long id, boolean held) {
        return jdbc.update("UPDATE person SET held = ? WHERE sheet_id = ? AND id = ? AND held = ?", held, sheetId, id, !held) == 1;
    }

    private static Person map(ResultSet rs, int n) throws SQLException {
        Date retired = rs.getDate("retired_from");
        return new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"), null, rs.getLong("version"),
                retired == null ? null : retired.toLocalDate().toString(), rs.getBoolean("held"), List.of());
    }
}
