package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the date is blank or yyyy-MM-dd. */
public class ValidateRetire {
    public void validate(@RequestBody RetireRequest request, Out<Retirement> retirement) throws InvalidPersonException {
        String from = request == null || request.from() == null ? "" : request.from().trim();
        LocalDate parsed = null;
        if (!from.isEmpty()) {
            try {
                parsed = LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The retirement date must be yyyy-MM-dd");
            }
        }
        retirement.set(new Retirement(parsed, request == null || request.by() == null ? "" : request.by().trim()));
    }
}
package net.officefloor.hq.app.person;

/** Body of retiring a person: the date they are retired from (blank: the sheet's today), and who retires them. */
public record RetireRequest(String from, String by) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A retirement once validated: the date (null when none was given, so the sheet's today) and who gives it. */
public record Retirement(LocalDate from, String by) {
}
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Closes an open period, fixing its due-total as it is now: the figures of the claims that count (a held person's OPEN or PENDING claims do not) whose date falls
 *  in it, each with its late charge, added up (skipping n/a). Closing a period already closed is refused. */
public class ClosePeriod {
    public void close(@Val Period period, @Val PeriodCloseRequest request, PeriodRepository periods,
            ClaimRepository claims, PersonRepository people, RateRepository rates, SettingRepository settings,
            SheetRepository sheets,
            Out<PeriodClose> closed)
            throws InvalidPeriodException {
        if (period.closed()) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed");
        }
        Map<Long, Person> byId = people.list(period.sheetId()).stream()
                .collect(Collectors.toMap(Person::id, (p) -> p));
        BigDecimal floor = settings.floor(period.sheetId());
        LateCharge late = LateCharge.of(period.sheetId(), sheets, settings, claims);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : claims.list(period.sheetId())) {
            Person person = byId.get(c.personId());
            if (!ClaimDue.countsLive(c, person != null && person.held()) || c.date().isBefore(period.from()) || c.date().isAfter(period.to())) {
                continue;
            }
            BigDecimal figure = person == null ? c.due() : late.add(c, ClaimDue.figure(c, person.gradeOn(c.date()), rates, floor, late.rounding()));
            if (figure != null) {
                total = total.add(figure);
            }
        }
        if (!periods.close(period, total)) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed");
        String sheetId = person.sheetId();
        var today = sheets.today(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        LateCharge late = LateCharge.of(sheetId, sheets, settings, claims);
        List<Claim> mine = claims.list(sheetId).stream().filter((c) -> c.personId() == person.id()).toList();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean figured = false;
        int counted = 0;
        for (Claim c : mine) {
            if (!ClaimDue.countsLive(c, person.held())) {
                claims.bind(c, false, null);
                continue;
            }
            BigDecimal figure = ClaimDue.figure(c, person.gradeOn(c.date()), rates, floor, late.rounding());
            figured |= figure != null;
            if (figure != null) {
                total = total.add(late.add(c, figure));
            }
            counted++;
            claims.bind(c, true, figure);
        }
    /** Every person's figures on the sheet now, in the order they were added. */
    public RollupBefore take(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        LateCharge late = LateCharge.of(sheetId, sheets, settings, claims);
        List<Claim> all = claims.list(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            boolean figured = false;
            for (Claim c : all) {
                if (c.personId() != person.id() || !ClaimDue.countsLive(c, person.held())) {
                    continue;
                }
                claimed = claimed.add(c.amount());
                BigDecimal figure = late.add(c, ClaimDue.figure(c, person.gradeOn(c.date()), rates, floor, late.rounding()));
                figured |= figure != null;
                if (figure != null) {
                    due = due.add(figure);
                }

